  Theorem inst_RHEAP_frame : RHEAP_frame (KHp p).
  Proof.
    intros x LB m m' W R MU WM FW.
    pose proof R as (HA & IDS & LEN & AWV & FLX & DEP0 & DPL & DTR & DJ1 & DJ2 & EF & MF & DJD & TH & TLS & ASV & DAP & DSEC & PINV & SPR). pose proof (proj1 DAP) as DSB.
    assert (AG : agree_on (iprotected x) m m').
    { intros a Pa Ha. apply MU. rewrite wa_unsigned by lia.
      clear - FW Pa R. induction W as [|[lo hi] W IH]; [exact I|]. cbn.
      inversion FW as [|iv l CW FW']; subst. split; [| apply IH; exact FW'].
      intros K. exact (client_window_protected x LB m lo hi a R CW K Pa). }
    cbn [as_RHEAP KHp]. unfold IRHEAP. cbv zeta.
    split.
    { (* [comment removed for export] *) eapply (ARHEAP_frame_ok _ _ _ _ _ HA MU WM). eapply Forall_impl; [| exact FW].
      intros iv CW. exact (client_window_bridge x LB m iv R CW). }
    split; [exact IDS|]. split; [exact LEN|].
    split; [exact (awin_vis_wmono _ _ _ AWV WM)|].
    split.
    { (* [comment removed for export] *) destruct FLX as (F1 & F2 & (g & F3) & F4 & (b & F5)).
      split; [| split; [| split; [| split]]].
      - eapply (rw_cells_transport_pt _ _ _ AG WM); [exact F1|]. intros a Ha. unfold iprotected. cbn in Ha. lia.
      - eapply (rw_cells_transport_pt _ _ _ AG WM); [exact F2|]. intros a Ha. unfold iprotected. cbn in Ha. lia.
      - exact (sspguard_rw_any m').
      - eapply (rw_cells_transport_pt _ _ _ AG WM); [exact F4|]. intros a Ha. unfold iprotected. cbn in Ha. lia.
      - exists b. eapply (rw_cells_transport_pt _ _ _ AG WM); [exact F5|]. intros a Ha. unfold iprotected. cbn in Ha. lia. }
    split.
    { (* [comment removed for export] *) destruct DEP0 as [DWF DM]. split; [exact DWF|]. exact (depot_mem_frame x _ m m' DWF DM AG WM eq_refl eq_refl). }
    split; [exact DPL|]. split; [exact DTR|]. split; [exact DJ1|]. split; [exact DJ2|]. split; [exact EF|]. split; [exact MF|]. split; [exact DJD|].
    split.
    { (* [comment removed for export] *) destruct TH as (A1 & A2 & A3). split; [| split; [| exact A3]].
      - eapply (rw_cells_transport_pt _ _ _ AG WM); [exact A1|]. intros a Ha. unfold iprotected, AsIface.ATP, AllocRep.ATP in *. cbn in Ha. lia.
      - eapply (rw_cells_transport_pt _ _ _ AG WM); [exact A2|]. intros a Ha. unfold iprotected, AsIface.ATP, AllocRep.ATP in *. cbn in Ha. lia. }
    split.
    { (* [comment removed for export] *) destruct TLS as (tb & te & T48). exists tb, te.
      eapply (rw_cells_transport_pt _ _ _ AG WM); [exact T48|]. intros a Ha. unfold iprotected. cbn in Ha. lia. }
    split; [exact ASV|]. split; [exact DAP|]. split; [exact DSEC|]. split; [exact PINV|].
    (* [comment removed for export] *) intros a Ha. apply WM. exact (SPR a Ha).
  Qed.
End Laws3.
